  {claim.dispositions.map(d=><Card key={d.id}><CardHeader title={uiText(d.kind==='Allowance'?'折让':d.kind==='ReturnRefund'?'退货退款':d.kind==='Replace'?'换货补发':'返修')} tools={status(d.state)}/><div className="mist-card-body"><KeyValue items={[{label:'金额',value:money(d.amount)+' '+(d.goodsSource?.currency??w.state?.invoices.find(i=>i.id===claim.invoiceId)?.currency??'')},{label:'货物',value:d.quantity?d.quantity+' '+d.unit:'不涉及货物'},...(d.goodsSource?[{label:'批准实物来源',value:d.goodsSource.style+' · '+d.goodsSource.name+' · 原单价 '+money(d.goodsSource.unitPrice)+' '+d.goodsSource.currency+' · CI条目 '+d.goodsSource.sourceQuantity+' '+d.goodsSource.unit}]:[]),{label:'依据',value:d.basis},{label:'审批意见',value:d.decisionNote||'—'}]}/><SourceFiles ids={d.fileIds}/><div className="mist-row">{d.supersededById&&<Pill>{uiText("已修订为新处置")}</Pill>}{can&&!['Closed','Cancelled'].includes(claim.state)&&canEditPlatformClaimDraft(d)&&<Button onClick={()=>newDisposition(claim,d,true)}>{uiText("编辑草稿")}</Button>}{can&&d.state==='rejected'&&!d.supersededById&&<Button onClick={()=>newDisposition(claim,d)}>{uiText("按意见修订为新处置")}</Button>}{can&&['Draft','rejected'].includes(d.state)&&!d.supersededById&&<Button disabled={busy} onClick={()=>void execute({type:'platform.claim.submit',payload:{id:d.id}})}>{uiText("提交审批")}</Button>}{can&&d.state==='pending'&&d.reviewerId===w.session.user?.id&&<Button onClick={()=>setEditor({title:'决定索赔处置',fields:[f('decision','决定','select',{options:[{value:'approved',label:'批准'},{value:'rejected',label:'退回'}]}),f('note','审批意见','textarea')],initialValues:{decision:'',note:''},submit:v=>w.command({type:'platform.claim.decide',payload:{id:d.id,decision:str(v,'decision') as 'approved'|'rejected',note:str(v,'note')}})})}>{uiText("记录审批决定")}</Button>}{can&&d.state==='approved'&&<Button disabled={busy} onClick={()=>generate(claim,d)}>{uiText("生成履行单据")}</Button>}{can&&d.state==='approved'&&d.kind!=='Allowance'&&!warehouses.length&&<Button onClick={()=>w.go('inventory',undefined,{section:'claim:'+claim.id})}>{uiText("登记真实仓库")}</Button>}</div></div></Card>)}
  {(w.platform?.credits??[]).filter(n=>n.claimId===claim.id).map(n=><Card key={n.id} id={'mist-claim-credit-'+claim.id+'-'+n.id}><CardHeader title={uiText('贷项通知单 '+n.code)}/><div className="mist-card-body"><KeyValue items={[{label:'当前面额',value:money(platformCreditEffectiveAmount(n))+' '+n.currency},{label:'未结清余额',value:money(platformCreditRemaining(w.state!,n.id))+' '+n.currency}]}/>{n.schemaVersion===1?<DataTable rows={n.sourceVersions??[]} rowKey={version=>version.id} columns={[{key:'version',header:'正式来源版本',render:version=><Mono>V{version.version}</Mono>},{key:'amount',header:'批准金额',align:'right',render:version=>money(version.amount)+' '+version.currency},{key:'state',header:'打印状态',render:version=>n.printVersions?.some(issued=>issued.sourceVersionId===version.id)?<Pill tone="ok">{uiText("已签发")}</Pill>:<Pill>{uiText("草稿预览")}</Pill>},{key:'actions',header:'文档',render:version=>{const issued=n.printVersions?.find(row=>row.sourceVersionId===version.id);return <div className="mist-row">{read&&!issued&&<Button variant="quiet" disabled={busy||version.id!==n.currentVersionId} onClick={()=>void perform(()=>w.prepareCreditDocument(n.id,version.id))}>{uiText("预览草稿 V")}{version.version}</Button>}{can&&!issued&&<Button variant="quiet" disabled={busy||claim.state==='Cancelled'||version.id!==n.currentVersionId} onClick={()=>void perform(()=>w.issueCreditDocument(n.id,version.id))}>{uiText("签发正式 V")}{version.version}</Button>}{read&&issued&&<Button variant="quiet" disabled={busy} onClick={()=>void perform(()=>w.downloadCreditDocument(n.id,issued.id))}>{uiText("下载正式 V")}{version.version}</Button>}</div>;}}]}/>:<Banner title={uiText("历史贷项记录")}>{uiText("保留原金融事实；缺少完整正式来源版本，不自动补造打印或库存历史。")}</Banner>}<div className="mist-row">
   {finance&&<Button onClick={()=>setEditor({title:'用贷项抵扣发票',fields:[f('invoiceId','同客户同币种发票','select',{options:(w.state?.invoices??[]).filter(i=>isActiveMistInvoice(i)&&i.currency===n.currency&&w.state?.orders.find(o=>o.id===i.orderId)?.customerId===n.customerId&&i.open>0).map(i=>({value:i.id,label:i.code+' · 未收 '+money(i.open)}))}),f('amount','抵扣金额','number',{min:0.01,step:'0.01'})],initialValues:{invoiceId:'',amount:''},submit:v=>w.command({type:'platform.credit.apply',payload:{creditId:n.id,invoiceId:str(v,'invoiceId'),amount:num(v,'amount')}})})}>{uiText("抵扣发票")}</Button>}
   {finance&&<Button onClick={()=>setEditor({title:'登记实际现金退款',fields:[f('amount','实际退款金额','number',{min:0.01,step:'0.01'}),f('date','付款日期','date'),f('reference','实际付款凭据 / 参考号')],initialValues:{amount:'',date:today(),reference:''},submit:v=>w.command({type:'platform.credit.refund',payload:{creditId:n.id,amount:num(v,'amount'),date:str(v,'date'),reference:str(v,'reference')}})})}>{uiText("登记实际退款")}</Button>}</div></div></Card>)}
  {(w.platform?.claimGoods??[]).filter(g=>g.claimId===claim.id).map(g=>{const receipt=w.state?.fulfillment.returnReceipts.find(row=>row.id===g.returnReceiptId);return <Card key={g.id}><CardHeader title={uiText('退回履行 · '+g.quantity+' '+g.unit)} tools={status(g.state)}/><div className="mist-card-body">{g.source?<><KeyValue items={[{label:'正式退货单',value:<Mono>{receipt?.code??(w.session.hasPermission('inventory:read')?'缺少真实退货单':'当前岗位无权查看仓储详情')}</Mono>},{label:'来源商品',value:g.source.style+' · '+g.source.name},{label:'计划 / 实收',value:g.quantity+' / '+(g.receivedQuantity??0)+' '+g.unit},{label:'仓库',value:w.state?.fulfillment.warehouses.find(row=>row.id===receipt?.warehouseId)?.name??(w.session.hasPermission('inventory:read')?'—':'当前岗位无权查看仓储详情')}]}/><div className="mist-row">{inventory&&receipt&&<Button onClick={()=>w.go('inventory',receipt.id,{section:'claim:'+claim.id})}>{uiText("办理退货入库 / 报废")}</Button>}</div>{g.destination!=='Scrap'&&<Banner title={uiText("等待真实放行事实")}>{uiText("返修与换货补发必须形成实际专业记录，不能仅修改状态为待发运或已发出。")}</Banner>}</>:<Banner title={uiText("历史履行记录")}>{uiText("保留既有签收 / 报废事实；本轮不补造库存流水。")}</Banner>}{g.events.map((event,index)=><p key={index}>{event.at.slice(0,10)} · {label[event.action as keyof typeof label]||event.action} · {event.basis}<SourceFiles ids={event.fileIds}/></p>)}</div></Card>;})}</>;
 if(editor&&editor.fields.length>3)return <ModuleEditorPage spec={editor} onClose={()=>setEditor(null)}/>;
 return <><ModuleWorkbench title={uiText("售后索赔")} rows={rows} searchText={row=>JSON.stringify([row.code,row.problem,label[row.state]])} columns={[{key:'code',header:'案件',render:row=><Mono>{row.code}</Mono>},{key:'problem',header:'客诉问题',render:row=>row.problem},{key:'count',header:'处置',render:row=>row.dispositions.length+' 条'},{key:'state',header:'状态',render:row=>status(row.state)}]} create={can?{title:'登记客诉案件',fields:[f('orderId','来源订单','select',{options:orderOptions(w.state)}),f('invoiceId','来源发票','select',{options:(w.state?.invoices??[]).filter(isActiveMistInvoice).map(i=>({value:i.id,label:i.code+' · '+i.order}))}),f('problem','客诉问题','textarea'),evidence],initialValues:{orderId:'',invoiceId:'',problem:'',fileId:''},submit:v=>w.command({type:'platform.claim.create',payload:{orderId:str(v,'orderId'),invoiceId:str(v,'invoiceId'),problem:str(v,'problem'),fileIds:ids(v)}})}:undefined} detail={detail} rowActions={[{label:'新增处置',disabled:row=>!can||['Cancelled','Closed'].includes(row.state),run:row=>newDisposition(row)},{label:'关闭已结清案件',disabled:row=>!can||row.state!=='Processing',run:row=>w.command({type:'platform.claim.close',payload:{id:row.id}})},{label:'撤销案件',disabled:row=>!can||['Cancelled','Closed'].includes(row.state),run:row=>setEditor({title:'撤销客诉案件',fields:[f('reason','撤销原因','textarea')],initialValues:{reason:''},submit:v=>w.command({type:'platform.claim.cancel',payload:{id:row.id,reason:str(v,'reason')}})})}]} exportRows={(filtered=rows)=>downloadModuleCsv('客诉案件.csv',['案件','问题','状态','处置条数','登记时间'],filtered.map(row=>[row.code,row.problem,row.state,row.dispositions.length,row.createdAt]))}/><ModuleEditorDialog spec={editor} onClose={()=>setEditor(null)}/></>;
