export function buildPlatformReport(state:NonNullable<ReturnType<typeof useMistWorkspace>['state']>,from='',to='',currency=''){const orders=state.orders.filter(o=>(!from||o.createdAt.slice(0,10)>=from)&&(!to||o.createdAt.slice(0,10)<=to)&&(!currency||o.currency===currency));const invoices=state.invoices.filter(i=>isRecognizedMistInvoice(i)&&orders.some(o=>o.id===i.orderId));return [...new Set(orders.map(o=>o.currency))].map(currency=>({id:currency,currency,orders:orders.filter(o=>o.currency===currency).length,amount:orders.filter(o=>o.currency===currency).reduce((s,o)=>s+mistMoneyMinor(o.amount),0)/100,invoiced:invoices.filter(i=>i.currency===currency).reduce((s,i)=>s+mistMoneyMinor(i.amount),0)/100,open:invoices.filter(i=>i.currency===currency).reduce((s,i)=>s+mistMoneyMinor(i.open),0)/100}));}
type DashboardTab='overview'|'team';
/** 业务全景；业务主管（客户管理主管权限）与所有者多一个“团队”页签，看下属名下在手的事并督办。 */
export function DashboardPage(){const w=usePlatform();const owner=w.workspace?.access?.role!=='member',canTeam=owner||w.session.hasPermission('relations:admin');const weekly=w.route.section==='team-weekly',tab:DashboardTab=canTeam&&(w.route.section==='team'||weekly)?'team':'overview';
  const members=workspaceMembers(w.workspace,w.state,w.session.user),viewer={id:w.session.user?.id??'',owner};
  return <MistPage><PageHeader description={uiText(tab==='team'?'团队成员名下在手的订单、待办、逾期与久未跟进客户。点成员看明细，对具体对象督办。':'本公司的订单履行、应收与风险概况。点击进入来源模块继续处理。')} title={uiText("业务全景")}/><ErrorNotice/>
    {canTeam&&<div className="mist-section"><Tabs<DashboardTab> value={tab} onChange={next=>w.go('dashboard',undefined,{section:next})} options={[{value:'overview',label:'业务全景'},{value:'team',label:'团队'}]}/></div>}
    {tab==='team'?(w.state?<TeamBoard state={w.state} members={members} viewer={viewer} can={w.session.hasPermission('relations:admin')} busy={w.loading||w.saving||!!w.pending} run={c=>w.isCurrent()?w.run(c):Promise.resolve(undefined)} go={(view,id,extra)=>w.go(view as any,id,extra as any)} key={weekly?'weekly':'team'} initialMode={weekly?'week':'now'} initialWeek={weekly?addBusinessDays(weekStartOf(today()),-7):undefined}/>:<EmptyState title={uiText("正在读取团队数据")} compact/>):<DashboardOverview/>}
  </MistPage>;}
function DashboardOverview(){const w=usePlatform();const active=w.state?.orders.filter(o=>o.progress<100)??[],due=w.state?.invoices.filter(i=>isActiveMistInvoice(i)&&i.open>0&&i.due<today())??[],risks=w.platform?.risks.filter(r=>r.state!=='Resolved')??[];const late=w.state?buildOrderProgress(w.state,today()).filter(r=>r.status==='overdue'):[],aging=w.state?buildReceivableAging(w.state,today()):[];const agingByCurrency=[...new Set(aging.map(r=>r.currency))].map(currency=>({id:currency,currency,...Object.fromEntries([...AGING_BUCKETS.map(b=>b.key),'total'].map(k=>[k,aging.filter(r=>r.currency===currency).reduce((s,r)=>s+mistMoneyMinor((r as any)[k]),0)/100]))})) as Array<{id:string;currency:string}&Record<string,number>>;return <><StatGrid><StatCard icon={Package} label={uiText("履行中订单")} value={active.length} onClick={()=>w.go('orders')}/><StatCard icon={Package} label={uiText("逾期未完成订单")} value={late.length} onClick={()=>w.go('reports',undefined,{section:'orders'})}/><StatCard icon={Receipt} label={uiText("逾期未收发票")} value={due.length} onClick={()=>w.go('reports',undefined,{section:'aging'})}/><StatCard icon={ShieldCheck} label={uiText("待处理风险")} value={risks.length} onClick={()=>w.go('risks')}/><StatCard icon={Users} label={uiText("进行中客诉")} value={w.platform?.claims.filter(c=>!['Closed','Cancelled'].includes(c.state)).length??0} onClick={()=>w.go('claims')}/></StatGrid><section className="mist-section"><Card><CardHeader title={uiText("订单履行")}/><DataTable rows={active} rowKey={r=>r.id} loading={w.loading} columns={[{key:'order',header:'订单',render:r=><SourceOrder id={r.id}/>},{key:'customer',header:'客户',render:r=>r.customer},{key:'due',header:'交期',render:r=>r.due},{key:'progress',header:'履行进度',render:r=><Meter segments={[{value:r.progress,tone:"accent"}]} caption={uiText(r.progress+"%")}/>},{key:'state',header:'当前状态',render:r=><Pill tone={r.tone}>{r.state}</Pill>}]} empty={<EmptyState title={uiText("没有履行中的订单")} description={uiText("业务数据建立后将在这里汇总。")}/>}/></Card></section><section className="mist-section"><Card><CardHeader title={uiText("应收账龄")} sub={uiText("截至 "+today()+" · 按币种分别统计")} tools={<Button variant="quiet" onClick={()=>w.go('reports',undefined,{section:'aging'})}>{uiText("查看明细")}<ArrowRight size={14}/></Button>}/><DataTable ariaLabel={uiText("应收账龄概览")} rows={agingByCurrency} rowKey={r=>r.id} columns={[{key:'currency',header:'币种',render:r=>r.currency},...AGING_BUCKETS.map(b=>({key:b.key,header:b.label,align:'right' as const,render:(r:Record<string,number|string>)=>money(Number(r[b.key]))})),{key:'total',header:'未收合计',align:'right',render:r=><b>{money(r.total)}</b>}]} empty={<EmptyState title={uiText("没有未收应收")} compact/>}/></Card></section></>;}
export function platformDataIssues(state:NonNullable<ReturnType<typeof useMistWorkspace>['state']>){const issues:Array<{id:string;kind:string;code:string;detail:string}>=[];for(const l of state.orderLines)if(!state.orders.some(o=>o.id===l.orderId))issues.push({id:'line:'+l.id,kind:'订单条目',code:l.style||l.name,detail:'关联订单不可见或不存在'});for(const i of state.invoices)if(!state.orders.some(o=>o.id===i.orderId))issues.push({id:'invoice:'+i.id,kind:'发票',code:i.code,detail:'关联订单不可见或不存在'});for(const a of state.allocations)if(!state.invoices.some(i=>i.id===a.invoiceId)||!state.receipts.some(r=>r.id===a.receiptId))issues.push({id:'allocation:'+a.id,kind:'核销明细',code:a.id,detail:'关联发票或到账流水不可见或不存在'});return issues;}
export function DataCenterPage(){const w=usePlatform(),issues=w.state?platformDataIssues(w.state):[];const rows=w.state?[{id:'orders',name:'订单',count:w.state.orders.length,view:'orders'},{id:'customers',name:'客户',count:w.state.customers.length,view:'relations'},{id:'invoices',name:'发票',count:w.state.invoices.length,view:'invoices'},{id:'receipts',name:'到账流水',count:w.state.receipts.length,view:'payment-vouchers'},{id:'products',name:'数字档案（产品）',count:w.state.market?.products?.length??0,view:'products'},{id:'suppliers',name:'供应商',count:w.state.market?.suppliers?.length??0,view:'suppliers'},{id:'purchases',name:'采购合同',count:w.state.fulfillment?.purchases?.length??0,view:'procurement'},{id:'shipments',name:'出运',count:w.state.fulfillment?.shipments?.length??0,view:'shipments'},{id:'documents',name:'单据',count:w.state.fulfillment?.documents?.length??0,view:'document-center'},{id:'files',name:'文件',count:w.state.files.length,view:'document-center'}]:[];return <MistPage><PageHeader title={uiText("数据中心")} actions={<Button icon={RefreshCw} loading={w.loading} onClick={()=>void w.refresh()}>{uiText("刷新数据")}</Button>}/><ErrorNotice/><StatGrid><StatCard icon={Building2} label={uiText("本公司")} value={w.workspace?.name??'—'}/><StatCard icon={Database} label={uiText("数据版本")} value={w.workspace?.revision??'—'}/><StatCard icon={ShieldCheck} label={uiText("关联问题")} value={issues.length}/></StatGrid><section className="mist-section mist-grid"><Card className="mist-col-6"><CardHeader title={uiText("业务数据")}/><DataTable rows={rows} rowKey={r=>r.id} columns={[{key:'name',header:'对象',render:r=>r.name},{key:'count',header:'记录数',align:'right',render:r=>r.count},{key:'view',header:'来源',render:r=><Button variant="quiet" onClick={()=>w.go(r.view)}>{uiText("查看")}<ArrowRight size={14}/></Button>}]}/></Card><Card className="mist-col-6"><CardHeader title={uiText("关联完整性")}/><DataTable rows={issues} rowKey={r=>r.id} columns={[{key:'kind',header:'对象',render:r=>r.kind},{key:'code',header:'标识',render:r=><Mono>{r.code}</Mono>},{key:'detail',header:'问题',render:r=>r.detail}]} empty={<EmptyState title={uiText("已检查关联没有发现问题")} description={uiText("覆盖订单条目、发票来源及核销双方关联；不代表未实现模块已通过验收。")} compact/>}/></Card></section><section className="mist-section"><Card><CardHeader title={uiText("最近业务记录")}/><DataTable rows={(w.state?.events??[]).slice(0,30)} rowKey={r=>r.id} columns={[{key:'time',header:'时间',render:r=>r.at},{key:'actor',header:'操作人',render:r=>r.actor},{key:'text',header:'事实',render:r=>r.text}]} empty={<EmptyState title={uiText("尚无业务记录")} description={uiText("完成业务操作后显示。")} compact/>}/></Card></section></MistPage>;}
export function BusinessToolsPage(){const w=usePlatform();const [input,setInput]=React.useState(''),[from,setFrom]=React.useState('m'),[to,setTo]=React.useState('yd');const factors:Record<string,number>={m:1,yd:0.9144,cm:0.01,in:0.0254};const value=input.trim()!==''&&Number.isFinite(Number(input))&&Number(input)>=0?Number(input)*factors[from]/factors[to]:null;return <MistPage><PageHeader title={uiText("业务工具")}/><section className="mist-grid"><Card className="mist-col-6"><CardHeader title={uiText("长度换算")} sub={uiText("采用国际码与英寸定义；本地计算不会写入订单。")}/><div className="mist-card-body"><FormGrid><Field label={uiText("原始长度")}><TextInput type="number" min={0} value={input} onChange={e=>setInput(e.target.value)}/></Field><Field label={uiText("原单位")}><Select value={from} options={Object.keys(factors).map(s=>({value:s,label:s}))} onChange={e=>setFrom(e.target.value)}/></Field><Field label={uiText("目标单位")}><Select value={to} options={Object.keys(factors).map(s=>({value:s,label:s}))} onChange={e=>setTo(e.target.value)}/></Field></FormGrid><SummaryBar items={[{label:'换算结果',value:value===null?'输入非负长度':money(value,4)+' '+to}]}/></div></Card><BusinessCalculators/><Card className="mist-col-6"><CardHeader title={uiText("常用业务计算")}/><div className="mist-card-body"><p>{uiText("成本和定价结果关联订单，并保存参数与计算依据。")}</p><div className="mist-row"><Button icon={Calculator} onClick={()=>w.go('pricing')}>{uiText("退税美元定价")}</Button><Button onClick={()=>w.go('bom')}>{uiText("成本与利润核算")}</Button></div><p>{uiText("开具与收付业务从真实订单和发票继续。")}</p><div className="mist-row"><Button onClick={()=>w.go('invoices')}>{uiText("商业发票")}</Button><Button onClick={()=>w.go('payment-vouchers')}>{uiText("收款核销")}</Button><Button onClick={()=>w.go('reports')}>{uiText("业务报表")}</Button></div></div></Card></section></MistPage>;}
const exporterFields:Array<{key:keyof CompanyExporterProfileValue;label:string}>=[{key:'nameEn',label:'出口方英文名'},{key:'beneficiary',label:'受益人'},{key:'addressEn',label:'英文地址'},{key:'bankName',label:'银行名称'},{key:'swiftCode',label:'SWIFT'},{key:'bankAddress',label:'银行地址'},{key:'usdAccountNumber',label:'USD收款账号'}];
function ExporterProfilePanel(){const session=useMistSession();const [value,setValue]=React.useState<CompanyExporterProfileValue|null>(null),[version,setVersion]=React.useState<number|null>(null),[configured,setConfigured]=React.useState<boolean|null>(null),[reason,setReason]=React.useState(''),[error,setError]=useRouteDraft(''),[busy,setBusy]=React.useState(false),[loading,setLoading]=React.useState(true);const key=React.useRef(session.sessionKey);key.current=session.sessionKey;const sequence=React.useRef(0);const toast=useToast();const canWrite=session.hasPermission('dictionary:write')&&session.hasRole('owner','admin');const read=React.useCallback(async()=>{const serial=++sequence.current,bound=key.current;setLoading(true);setError('');try{const response=await apiService.getCompanyExporterProfile();if(serial===sequence.current&&bound===key.current){setValue(response.value);setVersion(response.version);setConfigured(response.configured??!response.isDefault);}}catch(e){if(serial===sequence.current&&bound===key.current)setError(e instanceof Error?e.message:'配置读取失败');}finally{if(serial===sequence.current&&bound===key.current)setLoading(false);}},[]);React.useEffect(()=>{setValue(null);setConfigured(null);setReason('');void read();return()=>{sequence.current++;};},[session.sessionKey,read]);return <><Toolbar right={<Button icon={RefreshCw} disabled={busy} loading={loading} onClick={()=>void read()}>{uiText("重新读取")}</Button>}><span className="mist-note">{uiText("维护服务器出口方档案。变更进入系统配置历史，由现有权限核验。")}</span></Toolbar>{error&&<Banner tone="bad" title={uiText("配置操作未完成")}>{uiText(error)}</Banner>}{configured===false&&<Banner tone="warn" title={uiText("尚未配置出口方档案")}>{uiText("报价单、合同、商业发票、装箱单等单据在填写前无法生成。请填写公司英文名与地址等信息后保存；首次填写银行信息需同时填写变更原因。")}</Banner>}<section className="mist-grid"><Card className="mist-col-8"><CardHeader title={uiText("出口方与收款档案")} sub={uiText(version===null?'加载中':configured===false?'未配置':'服务器版本 '+version)}/><div className="mist-card-body">{value?<><FormGrid>{exporterFields.map(f=><Field key={f.key} label={uiText(f.label)} required={f.key==='nameEn'}><TextInput value={value[f.key]??''} disabled={!canWrite||busy} onChange={e=>setValue({...value,[f.key]:e.target.value})}/></Field>)}<Field label={uiText("变更原因（银行字段变更必填）")} full><TextArea value={reason} disabled={!canWrite||busy} onChange={e=>setReason(e.target.value)}/></Field></FormGrid><Button variant="primary" disabled={!canWrite||busy||loading} loading={busy} onClick={async()=>{const bound=key.current;setBusy(true);setError('');try{const result=await apiService.updateCompanyExporterProfile({value,reason});if(bound===key.current){setValue(result.value);setVersion(result.version);setConfigured(Boolean(result.value?.nameEn?.trim()));setReason('');toast('服务器配置已保存');}}catch(e){if(bound===key.current)setError(e instanceof Error?e.message:'配置保存失败');}finally{if(bound===key.current)setBusy(false);}}}>{uiText("保存服务器配置")}</Button></>:<EmptyState title={uiText(loading?'正在读取服务器配置':'尚未读取配置')} description={uiText("请通过重新读取重试。")}/>}</div></Card><Card className="mist-col-4"><CardHeader title={uiText("当前账号权限")}/><KeyValue items={[{label:'账号',value:session.user?.displayName??'—'},{label:'角色',value:session.user?.roleLabels?.map(r=>r.name).join('、')||session.user?.roles.join('、')||'—'},{label:'配置编辑',value:canWrite?'具备编辑条件；保存时服务器复核':'只读'}]}/><div className="mist-card-body"><Banner title={uiText("账号与员工档案分别管理")}>{uiText("账号、角色在“账号”中办理；部门、小组与员工档案在“人事管理”维护，档案不会改变账号角色或权限。")}</Banner></div></Card></section></>;}
