export const PLATFORM_PAGES:Record<string,React.FC>={invoices:InvoicePage,pricing:PricingPage,bom:BomPage,risks:RisksPage,claims:ClaimsPage,reports:PlatformReportsPage,dashboard:DashboardPage,'data-center':DataCenterPage,hr:HrOrganizationPage,'business-tools':BusinessToolsPage,'admin-panel':AdminPanelPage,assistant:AssistantPage};
